import React from 'react';
import { names } from '../../data';

function Tips({ range, tips, shifts, onBackBtnClick, onCalculateBtnClick, onTipsChange, onShiftsChange }) {
    return (
        <div>
            <div>
                <h3>Enter tips</h3>
            </div>
            <div className='table-container'>
                <table className='table'>
                    <thead>
                        <tr>
                            <th></th>
                            <th>Morning Tip</th>
                            <th>Evening Tip</th>
                        </tr>
                        <tr>
                            <th>
                                <input
                                    type="number"
                                    value={tips.find((tip) => tip.date === date.date)?.morningTip || 0}
                                    onChange={(e) =>
                                        onTipsChange(date.date, "morningTip", e.target.value)
                                    }
                                    // Add this line to select the text on click
                                    onClick={(e) => e.target.select()}
                                    // Set to 0 if the input is empty
                                    onBlur={(e) => {
                                        if (e.target.value === "") {
                                            onTipsChange(date.date, "morningTip", 0);
                                        }
                                    }}
                                />
                            </th>
                        </tr>
                    </thead>
                </table>
            </div>
        </div>
    );
}

export default Tips;
